import React, { useEffect, useRef } from 'react';
import { View, StyleSheet, Image, Animated, useWindowDimensions } from 'react-native';
import { useNavigation } from '@react-navigation/native';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';
import { AuthStackParamList } from '../../navigation/types';
import theme from '../../theme';

const SplashScreen = () => {
  const fadeAnim = React.useRef(new Animated.Value(0)).current;
  const navigation = useNavigation<NativeStackNavigationProp<AuthStackParamList, 'Splash'>>();
  const navigationTimeout = useRef<NodeJS.Timeout | null>(null);
  const { width: windowWidth, height: windowHeight } = useWindowDimensions();

  // Responsive sizing calculations
  const isSmallScreen = windowWidth < 375;
  const isMediumScreen = windowWidth >= 375 && windowWidth < 414;
  const isLargeScreen = windowWidth >= 414;

  const getResponsiveLogoSize = () => {
    if (isSmallScreen) return 120;
    if (isMediumScreen) return 140;
    return 160;
  };

  const getResponsiveCircleSize = () => {
    if (isSmallScreen) return 80;
    if (isMediumScreen) return 100;
    return 120;
  };

  const getResponsiveAppNameSize = () => {
    if (isSmallScreen) return 48;
    if (isMediumScreen) return 56;
    return 64;
  };

  const getResponsiveTaglineSize = () => {
    if (isSmallScreen) return 20;
    if (isMediumScreen) return 22;
    return 24;
  };

  useEffect(() => {
    Animated.timing(fadeAnim, {
      toValue: 1,
      duration: 1000,
      useNativeDriver: true,
    }).start();

    // Navigate to Onboarding screen after splash animation
    navigationTimeout.current = setTimeout(() => {
      navigation.replace('Onboarding');
    }, 2500); // Wait 2.5 seconds total (1s animation + 1.5s display)

    return () => {
      if (navigationTimeout.current) {
        clearTimeout(navigationTimeout.current);
      }
    };
  }, [fadeAnim, navigation]);

  return (
    <View style={styles.container}>
      <Animated.View style={[styles.logoContainer, { opacity: fadeAnim }]}>
        <View style={styles.logo}>
          <Image 
            source={require('../../../assets/logo/logo.jpg')}
            style={[
              styles.logoImage,
              { 
                width: getResponsiveLogoSize(), 
                height: getResponsiveLogoSize(),
                borderRadius: theme.borderRadius.lg 
              }
            ]}
            resizeMode="contain"
          />
        </View>
        <Animated.Text style={[styles.appName, { 
          opacity: fadeAnim, 
          fontSize: getResponsiveAppNameSize(),
          color: theme.colors.textInverse,
          fontWeight: '800',
          lineHeight: 60,
        }]}>
          Eventrix
        </Animated.Text>
        <Animated.Text style={[styles.tagline, { 
          opacity: fadeAnim, 
          fontSize: getResponsiveTaglineSize(),
          color: theme.colors.textInverse,
          fontWeight: '600',
          lineHeight: 30,
        }]}>
          Discover Events Near You
        </Animated.Text>
      </Animated.View>
    </View>
  );
};

