import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  ScrollView,
  TouchableOpacity,
  StyleSheet,
  TextInput,
  Modal,
  SafeAreaView,
  ActivityIndicator,
  Alert,
} from 'react-native';
import { Card, Button, Text as CustomText } from '../../components/common';

interface ComponentInfo {
  name: string;
  path: string;
  type: 'component' | 'screen' | 'navigation';
  category: string;
  content: string;
  imports: string[];
  exports: string[];
}

const ComponentPreviewScreen: React.FC = () => {
  const [components, setComponents] = useState<ComponentInfo[]>([]);
  const [filteredComponents, setFilteredComponents] = useState<ComponentInfo[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedComponent, setSelectedComponent] = useState<ComponentInfo | null>(null);
  const [searchText, setSearchText] = useState('');
  const [typeFilter, setTypeFilter] = useState<string>('all');
  const [categoryFilter, setCategoryFilter] = useState<string>('all');

  useEffect(() => {
    fetchComponents();
  }, []);

  useEffect(() => {
    filterComponents();
  }, [components, searchText, typeFilter, categoryFilter]);

  const fetchComponents = async () => {
    try {
      setLoading(true);
      const response = await fetch('http://localhost:3000/preview/api');
      if (!response.ok) {
        throw new Error('Failed to fetch components');
      }
      const data = await response.json();
      setComponents(data);
    } catch (error) {
      console.error('Error fetching components:', error);
      Alert.alert('Error', 'Failed to load components. Make sure the backend is running on localhost:3000');
    } finally {
      setLoading(false);
    }
  };

  const filterComponents = () => {
    let filtered = components;

    if (typeFilter !== 'all') {
      filtered = filtered.filter(comp => comp.type === typeFilter);
    }

    if (categoryFilter !== 'all') {
      filtered = filtered.filter(comp => comp.category === categoryFilter);
    }

    if (searchText) {
      filtered = filtered.filter(comp => 
        comp.name.toLowerCase().includes(searchText.toLowerCase()) ||
        comp.path.toLowerCase().includes(searchText.toLowerCase())
      );
    }

    setFilteredComponents(filtered);
  };

  const getCategories = () => {
    const categories = [...new Set(components.map(comp => comp.category))];
    return ['all', ...categories];
  };

  const getTypeColor = (type: string) => {
    switch (type) {
      case 'component': return '#3B82F6';
      case 'screen': return '#10B981';
      case 'navigation': return '#F59E0B';
      default: return '#6B7280';
    }
  };

  const renderComponentCard = (component: ComponentInfo) => (
    <Card key={component.name} style={styles.componentCard}>
      <TouchableOpacity onPress={() => setSelectedComponent(component)}>
        <View style={styles.cardHeader}>
          <View style={styles.titleContainer}>
            <CustomText style={styles.componentName}>{component.name}</CustomText>
            <View style={styles.badgeContainer}>
              <View style={[styles.badge, { backgroundColor: getTypeColor(component.type) }]}>
                <CustomText style={styles.badgeText}>{component.type}</CustomText>
              </View>
              <View style={[styles.badge, { backgroundColor: '#E5E7EB' }]}>
                <CustomText style={styles.badgeText}>{component.category}</CustomText>
              </View>
            </View>
          </View>
        </View>

        <CustomText style={styles.pathText}>{component.path}</CustomText>

        {component.exports.length > 0 && (
          <View style={styles.exportsContainer}>
            <CustomText style={styles.labelText}>Exports:</CustomText>
            <View style={styles.exportsList}>
              {component.exports.slice(0, 3).map((exportName, index) => (
                <View key={index} style={styles.exportBadge}>
                  <CustomText style={styles.exportText}>{exportName}</CustomText>
                </View>
              ))}
              {component.exports.length > 3 && (
                <CustomText style={styles.moreText}>+{component.exports.length - 3} more</CustomText>
              )}
            </View>
          </View>
        )}

        <CustomText style={styles.importsCount}>
          {component.imports.length} import{component.imports.length !== 1 ? 's' : ''}
        </CustomText>
      </TouchableOpacity>
    </Card>
  );

  const renderComponentModal = () => {
    if (!selectedComponent) return null;

    return (
      <Modal
        visible={!!selectedComponent}
        animationType="slide"
        presentationStyle="pageSheet"
      >
        <SafeAreaView style={styles.modalContainer}>
          <View style={styles.modalHeader}>
            <CustomText style={styles.modalTitle}>{selectedComponent.name}</CustomText>
            <TouchableOpacity onPress={() => setSelectedComponent(null)}>
              <CustomText style={styles.closeButton}>✕</CustomText>
            </TouchableOpacity>
          </View>

          <ScrollView style={styles.modalContent}>
            <View style={styles.detailSection}>
              <CustomText style={styles.detailLabel}>Type:</CustomText>
              <View style={[styles.badge, { backgroundColor: getTypeColor(selectedComponent.type) }]}>
                <CustomText style={styles.badgeText}>{selectedComponent.type}</CustomText>
              </View>
            </View>

            <View style={styles.detailSection}>
              <CustomText style={styles.detailLabel}>Category:</CustomText>
              <CustomText style={styles.detailValue}>{selectedComponent.category}</CustomText>
            </View>

            <View style={styles.detailSection}>
              <CustomText style={styles.detailLabel}>Path:</CustomText>
              <CustomText style={styles.detailValue}>{selectedComponent.path}</CustomText>
            </View>

            {selectedComponent.exports.length > 0 && (
              <View style={styles.detailSection}>
                <CustomText style={styles.detailLabel}>Exports:</CustomText>
                <View style={styles.modalExportsList}>
                  {selectedComponent.exports.map((exportName, index) => (
                    <View key={index} style={styles.exportBadge}>
                      <CustomText style={styles.exportText}>{exportName}</CustomText>
                    </View>
                  ))}
                </View>
              </View>
            )}

            {selectedComponent.imports.length > 0 && (
              <View style={styles.detailSection}>
                <CustomText style={styles.detailLabel}>Imports:</CustomText>
                {selectedComponent.imports.map((importName, index) => (
                  <CustomText key={index} style={styles.importItem}>• {importName}</CustomText>
                ))}
              </View>
            )}

            <View style={styles.detailSection}>
              <CustomText style={styles.detailLabel}>Source Code:</CustomText>
              <View style={styles.codeContainer}>
                <CustomText style={styles.codeText}>{selectedComponent.content}</CustomText>
              </View>
            </View>
          </ScrollView>
        </SafeAreaView>
      </Modal>
    );
  };

  if (loading) {
    return (
      <View style={styles.loadingContainer}>
        <ActivityIndicator size="large" color="#3B82F6" />
        <CustomText style={styles.loadingText}>Loading components...</CustomText>
      </View>
    );
  }

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.header}>
        <CustomText style={styles.title}>Component Preview</CustomText>
        <CustomText style={styles.subtitle}>{components.length} components found</CustomText>
      </View>

      <View style={styles.filtersContainer}>
        <TextInput
          style={styles.searchInput}
          placeholder="Search components..."
          value={searchText}
          onChangeText={setSearchText}
        />

        <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.filterScroll}>
          <View style={styles.filterButtons}>
            <TouchableOpacity
              style={[styles.filterButton, typeFilter === 'all' && styles.activeFilter]}
              onPress={() => setTypeFilter('all')}
            >
              <CustomText style={styles.filterText}>All</CustomText>
            </TouchableOpacity>
            <TouchableOpacity
              style={[styles.filterButton, typeFilter === 'component' && styles.activeFilter]}
              onPress={() => setTypeFilter('component')}
            >
              <CustomText style={styles.filterText}>Components</CustomText>
            </TouchableOpacity>
            <TouchableOpacity
              style={[styles.filterButton, typeFilter === 'screen' && styles.activeFilter]}
              onPress={() => setTypeFilter('screen')}
            >
              <CustomText style={styles.filterText}>Screens</CustomText>
            </TouchableOpacity>
            <TouchableOpacity
              style={[styles.filterButton, typeFilter === 'navigation' && styles.activeFilter]}
              onPress={() => setTypeFilter('navigation')}
            >
              <CustomText style={styles.filterText}>Navigation</CustomText>
            </TouchableOpacity>
          </View>
        </ScrollView>
      </View>

      <ScrollView style={styles.componentsList}>
        {filteredComponents.map(renderComponentCard)}
      </ScrollView>

      {renderComponentModal()}

      <View style={styles.refreshButton}>
        <Button onPress={fetchComponents} title="Refresh" />
      </View>
    </SafeAreaView>
  );
};

